import html
import json
import shutil
from pathlib import Path

import pandas as pd

from scripts.analysis.audit_approximate_distance import ROOT


def main():
    out=ROOT/"results/formal_approximate_correspondence"
    summary=json.loads((out/"publication_summary.json").read_text())
    ranks=pd.read_csv(out/"ranking_summary.csv")
    reconstruction=pd.read_csv(out/"reconstruction.csv")
    held=ranks[(ranks.family=="all")&(ranks.split=="heldout")].set_index("method")
    pub=ROOT/"docs/publications"
    pub.mkdir(parents=True,exist_ok=True)
    shutil.copyfile(ROOT/"output/pdf/approximate_computing_aig_correspondence_research.pdf",pub/"approximate_computing_aig_correspondence_research.pdf")
    assets=ROOT/"docs/presentation/assets/approximate"
    assets.mkdir(parents=True,exist_ok=True)
    for path in (ROOT/"paper/figures/approximate_correspondence").glob("*.png"):
        shutil.copyfile(path,assets/path.name)
    (ROOT/"docs/.nojekyll").touch()
    (ROOT/"docs/research-evidence.json").write_text(json.dumps(summary,indent=2)+"\n")
    svg='''<svg viewBox="0 0 650 260" role="img" aria-label="Source and optimized logic share the output ab while internal functions differ"><g fill="none" stroke="#166d68" stroke-width="2"><rect x="22" y="70" width="220" height="100" rx="4"/><rect x="392" y="70" width="220" height="100" rx="4"/><path d="M265 120H365m-15-10 15 10-15 10"/></g><g fill="#172c38" font-family="Georgia,serif" text-anchor="middle"><text x="132" y="40" font-size="20">Source</text><text x="502" y="40" font-size="20">Optimized</text><text x="132" y="113" font-size="28">s = a ∧ b</text><text x="502" y="113" font-size="28">t = a</text><text x="132" y="147" font-size="21">y = s</text><text x="502" y="147" font-size="21">y = t ∧ b</text><text x="325" y="220" font-size="22">Same outputs · Different internal functions</text></g></svg>'''
    slides=[]
    def slide(title,eyebrow,body,notes=""):
        slides.append(f'<section class="slide" data-title="{html.escape(title)}"><p class="eyebrow">{eyebrow}</p><h2>{title}</h2>{body}<aside class="notes">{html.escape(notes)}</aside></section>')
    def figure(name,caption):
        return f'<figure><img src="assets/approximate/{name}.png" alt="{html.escape(caption)}"><figcaption>{caption}</figcaption></figure>'
    slide("From approximate computing to exact correspondence","Research study · 22 October 2026",'<p class="lead">Measure internal disagreement. Ask whether it is observable. Use that information to guide an exact proof.</p><div class="rule">Approximate reasoning supports the search; accepted circuits still require exact correctness.</div>',"This study answers Carmine Rizzi’s question about the connection with approximate computing. It is a bounded research extension, not an approximate circuit optimizer.")
    slide("Same outputs, different internal functions","01 · The correspondence problem",svg+'<p class="lead">AIG rewriting, factoring, resubstitution, and don’t-care optimization can remove or invent internal functions.</p>',"The diagram is a controlled algebraic example. BLIF covers can represent larger gates even though the synthesis flows operate on AIGs.")
    slide("Three different questions","02 · Evidence hierarchy",'<div class="two"><div class="panel"><h3>Functional similarity</h3><p>How frequently do two internal functions disagree?</p><div class="equation small">d(f,g) = Pr[f ≠ g]</div><p>Useful as a candidate feature.</p></div><div class="panel"><h3>Historical lineage</h3><p>Which source function actually led to this optimized target?</p><p class="muted">Requires independent construction or provenance evidence.</p></div></div><p class="rule">Exact contextual replacement is a third claim: the outputs remain unchanged after substitution.</p>')
    slide("The measurement had to be repaired first","03 · Integrity audit",'<p class="lead">ABC’s output-0 BLIF covers were interpreted as constant zero by the old simulator and encoder.</p><div class="stats"><div class="stat"><strong>32 / 32</strong><span>selected historical values reproduced</span></div><div class="stat"><strong>16 / 16</strong><span>verified rows correct to zero + fresh CEC</span></div><div class="stat"><strong>16 / 16</strong><span>rejected controls remain non-equivalent</span></div></div><p class="caption">Fixed stratified replay; regenerated pairs lack old artifact hashes. The complete historical 2,609-row pool is not revalidated.</p>',"The old 76.5% path headline and historical approximate-distance conclusions are not reused as validated results here. The new scalar oracle independently checks the repaired measurements.")
    slide("Global error and contextual error","04 · Approximate-computing connection",'<div class="equation">d(t,s) = Pr[fₜ(X) ≠ gₛ(X)]</div><div class="equation">E(t,s) = Pr[O(X) ≠ O[t ← gₛ](X)]</div><p class="lead">The candidate cone is cloned from source primary inputs into the actual optimized consumer context.</p><p class="caption">Uniform independent primary inputs. Output Hamming, MAE, and WCE are also measured under an explicit output encoding.</p>')
    slide("Disagreement matters where it is observable","05 · Observability don’t-cares",'<div class="two"><div><div class="equation small">s = a ⊕ b &nbsp; · &nbsp; t = a<br>y = t ∧ ¬b</div><p class="lead">The source uses y = s ∧ ¬b.</p><div class="stats"><div class="stat"><strong>½</strong><span>global disagreement</span></div><div class="stat"><strong>0</strong><span>contextual error</span></div></div></div><div class="panel"><h3>Pointwise identity</h3><div class="equation small">output error = D(X) · oₜ(X)</div><p>Disagreement and observability can be dependent. Multiplying their average probabilities gives the wrong answer.</p></div></div>')
    slide("Rare does not mean safe","06 · Adversarial negative",'<div class="equation small">r = conjunction of remaining inputs<br>s = a ⊕ r &nbsp; · &nbsp; t = a &nbsp; · &nbsp; y = t ⊕ r</div><p class="lead">Substituting s for t makes every rare disagreement observable.</p><div class="rule">At eight inputs: d = E = 1/64. A distractor can be closer at 1/128 while still being the wrong ancestor and an unsafe exact replacement.</div>',"The committed SMT counterexamples replay as concrete named primary-input assignments. Low probability never discharges exact proof obligations.")
    slide("Exact counts, estimates, and proofs","07 · Measurement contract",'<div class="two"><div class="panel"><h3>Completed exact study</h3><ul><li>Exhaustive PI truth vectors</li><li>Independent scalar oracle</li><li>Z3 equality / output miters</li><li>Fresh ABC CEC for graph acceptance</li></ul></div><div class="panel"><h3>Sampling calibration</h3><ul><li>1,024 IID uniform samples</li><li>Seeds 7, 19, 41</li><li>Pointwise 95% Hoeffding intervals</li><li>No equivalence claim from sampled zero</li></ul></div></div><p class="caption">Ordinary SAT finds a counterexample or proves equality; nonzero probabilities here come from exhaustive counting.</p>')
    slide("Small, disclosed experimental denominators","08 · Experimental setup",f'<div class="stats"><div class="stat"><strong>{summary["controlled_cases"]}</strong><span>controlled algebraic rewrite cases</span></div><div class="stat"><strong>{summary["diagnostics"]}</strong><span>structural-path diagnostic targets</span></div><div class="stat"><strong>{summary["reconstruction_unique_targets"]}</strong><span>existing generated reconstruction targets</span></div></div><ul><li>Lineage study: six-input development, eight-input width holdout.</li><li>Diagnostics: generated adder, multiplier, ISCAS c17; balance and dc2.</li><li>Reconstruction: dc2 development, resyn2 flow holdout.</li></ul><p class="caption">Controlled labels and standard-netlist diagnostics stay separate. Paths are structural proxies; no new external RTL result is claimed.</p>')
    slide("Similarity is weak evidence of ancestry","09 · Held-out ranking",figure("lineage_ranking","Lineage Precision@1 on 24 held-out controlled cases")+f'<p class="caption">Hybrid P@1: {held.loc["hybrid","precision1"]:.1%}; structural P@1: {held.loc["structural","precision1"]:.1%}; global-distance P@1: {held.loc["global","precision1"]:.1%}. Contextual and hybrid features do not beat the structural baseline on this suite.</p>',"The methods have identical pools. Four queries have no designated ancestor. P@5, MRR, family-specific results, abstention, and single-feature null ablations are available in the report and CSVs.")
    slide("Context changes the interpretation","10 · Exact error analysis",figure("global_contextual","Controlled candidates: global versus contextual error")+'<p class="caption">Points below the diagonal have masked differences. Zero-context candidates can still have substantial global disagreement. This establishes interchangeability, not ancestry.</p>')
    slide("Approximate order, exact acceptance","11 · Reconstruction algorithm",'<ol class="lead"><li>Freeze the same ≤176 source-derived unary/binary proposals.</li><li>Rank by disagreement on eight sampled assignments.</li><li>Test exact equality under a fixed check budget.</li><li>Emit an active replacement and require both CEC scopes.</li></ol><p class="rule">Candidate-pool hashes, budgets, seeds, proof calls, failures, and artifacts are recorded for both orderings.</p><p class="caption">The default full grammar remains available. This experiment uses its unary/binary subset and still computes bounded exhaustive proposal vectors.</p>')
    slide("A search-ordering gain; unchanged full-budget recovery","12 · Reconstruction results",figure("reconstruction_budget","Accepted graph-active target IDs versus exact-check budget")+'<p class="caption">At budget 1: guided 1/10 development and 1/8 holdout; enumeration 0. At full budget: both recover the same target set. The two accepted flow instances share one distinct rewritten graph.</p>',"Each displayed count is per seed. Three seeds do not create three independent circuits. The paired holdout interval includes zero, and total runtime does not improve at this scale.")
    slide("What the path diagnostic does and does not show","13 · Critical-path back-mapping",f'<div class="stats"><div class="stat"><strong>25 / 26</strong><span>exact / complemented candidate available</span></div><div class="stat"><strong>{summary["diagnostic_near_5pct"]}</strong><span>extra nonzero near matches within 5%</span></div><div class="stat"><strong>{summary["diagnostic_odc_only"]}</strong><span>context-only exact interchangeability</span></div></div><p class="lead">No historical-lineage precision is computed for these targets. The diagnostic provides a contextual observation and a null result for global near-match coverage.</p>')
    slide("Conclusions and the next decisive experiment","14 · Research interpretation",'<ul><li>Approximate-computing metrics explain internal relationships.</li><li>Observability separates harmless differences from rare observable errors.</li><li>Approximation can prioritize an exact reconstruction search.</li><li>Similarity alone does not establish historical correspondence.</li></ul><div class="rule">Next: a larger checkpoint corpus with independently recorded lineage, disjoint design families, and matched wall-clock budgets against exact hashing or symbolic pruning.</div>')
    slide("Reproduce, inspect, and share","15 · Research artifacts",'<div class="document-list"><a href="../publications/approximate_computing_aig_correspondence_research.pdf">Academic report <span class="tag">PDF</span></a><a href="../approximate_computing_correspondence_research.md">Method and evidence ledger <span class="tag">Markdown</span></a><a href="https://github.com/stefi19/aig_optimization_experiments/tree/main/results/formal_approximate_correspondence">Frozen results and graph artifacts <span class="tag">GitHub</span></a><a href="legacy.html">Historical presentation <span class="tag">Superseded distances</span></a><a href="../">Research website <span class="tag">Home</span></a></div><p class="caption">make approx-correspondence · make check-approx-correspondence · make approx-correspondence-pdf</p>',"Background: Vašíček, Formal Methods for Exact Analysis of Approximate Circuits, IEEE Access 2019; ABC; DAG-aware rewriting; don't-care resynthesis. Full bibliography is in the PDF.")
    document='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Formal Approximate Correspondence</title><meta name="description" content="A validated research presentation on approximate computing, observability, and exact AIG correspondence reconstruction."><link rel="stylesheet" href="approximate.css"></head><body><header class="topbar"><a class="brand" href="../">AIG / CORRESPONDENCE</a><span>FORMAL APPROXIMATE RECOVERY · 2026</span><a href="../publications/approximate_computing_aig_correspondence_research.pdf">Read the report ↗</a></header><main class="deck">'''+''.join(slides)+'''</main><footer class="controls"><div class="progress" aria-hidden="true"><div class="progress-bar"></div></div><button id="prev" type="button" aria-label="Previous slide">Prev</button><span id="slide-number" aria-live="polite"></span><button id="next" type="button" aria-label="Next slide">Next</button><button id="notes-toggle" type="button" aria-expanded="false" aria-controls="notes-panel">Notes</button><button id="overview-toggle" type="button" aria-pressed="false">Overview</button><span class="shortcut">← → navigate · N notes · Home / End</span></footer><aside class="notes-panel" id="notes-panel" aria-label="Speaker notes"></aside><script src="approximate.js"></script></body></html>'''
    (ROOT/"docs/presentation/index.html").write_text(document)
    home=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>AIG Correspondence Research</title><meta name="description" content="Formal approximate correspondence research: validated error metrics, observability, and proof-guided exact reconstruction."><link rel="stylesheet" href="presentation/approximate.css"></head><body class="home"><header class="topbar"><a class="brand" href="./">AIG / CORRESPONDENCE</a><span>RESEARCH ARTIFACT · 22 OCTOBER 2026</span><a href="https://github.com/stefi19/aig_optimization_experiments">Repository ↗</a></header><main class="container"><section class="hero"><p class="eyebrow">Approximate reasoning. Exact correctness.</p><h1>Understanding logic after optimization.</h1><p class="lead">Synthesis preserves what a circuit computes while changing the functions inside it. We measure those differences, ask which are observable, and use the evidence to guide exact correspondence reconstruction.</p><div class="actions"><a class="button primary" href="presentation/">Open the presentation →</a><a class="button" href="publications/approximate_computing_aig_correspondence_research.pdf">Read the research PDF ↗</a></div></section><section class="home-section"><div class="stats"><div class="stat"><strong>{summary['controlled_cases']}</strong><span>controlled rewrite cases</span></div><div class="stat"><strong>{summary['diagnostics']}</strong><span>structural-path diagnostic targets</span></div><div class="stat"><strong>{summary['reconstruction_unique_targets']}</strong><span>unique reconstruction target IDs</span></div></div><p class="caption">Separate experimental denominators. Controlled algebraic lineage, generated netlist reconstruction, and standard-netlist diagnostics are not interchangeable evidence.</p></section><section class="home-section research-grid"><div><p class="eyebrow">The connection to approximate computing</p><h2>Internal disagreement is only part of the story.</h2><p>Two internal functions can differ on half of all input assignments yet be exactly interchangeable in their consumer context. A rare difference can also be observable every time it occurs.</p><p>Functional similarity supports explanation and candidate ordering. Every accepted reconstruction still needs exact local validation, an active graph artifact, and global equivalence checks.</p></div><div>{svg}</div></section><section class="home-section"><p class="eyebrow">Completed experiment</p><h2>A bounded search-ordering result.</h2><div class="research-grid"><figure><img src="presentation/assets/approximate/reconstruction_budget.png" alt="Accepted graph-active reconstruction targets under matched candidate-check budgets"><figcaption>Frozen candidate pools and budgets; three disclosed sampling seeds.</figcaption></figure><div><p>Sampled ordering reaches accepted artifacts at smaller exact-check budgets. At full budget, the accepted target set is unchanged. Two accepted flow instances share one distinct graph.</p><p>Global similarity performs poorly as historical-lineage evidence in the controlled suite. No broad external RTL gain or runtime speedup is claimed.</p></div></div></section><section class="home-section"><p class="eyebrow">Measurement integrity</p><h2>Corrected before extending the claims.</h2><p>The shared simulator and symbolic encoder ignored output-0 BLIF covers. A frozen 32-row replay reproduces the old values; all 16 selected verified examples become zero-distance and pass fresh ABC CEC after the fix. The historical distance files remain available with a supersession notice. The complete historical pool has not been revalidated.</p></section><section class="home-section" id="publications"><p class="eyebrow">Publications and reproducibility</p><h2>Inspect the evidence.</h2><div class="document-list"><a href="publications/approximate_computing_aig_correspondence_research.pdf">From Approximate Computing to Formal Approximate Correspondence Recovery <span class="tag">Research report · PDF</span></a><a href="presentation/">Formal approximate correspondence <span class="tag">16 HTML slides</span></a><a href="approximate_computing_correspondence_research.md">Method, limitations, and claim-to-evidence table <span class="tag">Research note</span></a><a href="professor_approximate_computing_report.md">Concise supervisor-facing findings <span class="tag">Short report</span></a><a href="https://github.com/stefi19/aig_optimization_experiments/tree/main/results/formal_approximate_correspondence">Frozen results, independent checker, and BLIF artifacts <span class="tag">GitHub</span></a><a href="presentation/legacy.html">Previous research presentation <span class="tag">Historical snapshot</span></a></div></section></main><footer class="home-footer container">AIG Optimization Correspondence Experiments · Exact evidence remains distinct from approximate similarity.</footer></body></html>'''
    (ROOT/"docs/index.html").write_text(home)
    print(f"Built website and {len(slides)} slides from checked result tables")


if __name__=="__main__":
    main()
